    await page.goto('/');
    await expect(page.getByTestId('app-root')).toBeVisible();

    // The nav entry keeps its stable testid (nav-projects) but its visible label is now "Jobs".
    await expect(page.getByTestId('nav-projects')).toHaveText('Jobs');
