1	// Acceptance tests for the change request:
2	//   "When I open a project I want to see its invoices. Show me what they add up to. Let me add a
3	//    new invoice for an amount."
4	//
5	// Opening a project (project-open-<id> from the projects list) reaches that project's detail page.
6	// The detail page lists the project's OWN invoices (each with its amount), shows what they ADD UP
7	// TO, and offers a form to add a new invoice for an amount. After adding, the new invoice appears
8	// and the total reflects it.
9	//
10	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed; the add flow is
11	// driven through the form. Seed honours clients: { id, name, email }, projects: { id, clientId,
12	// name } and invoices: { id, projectId, amount }.
13	//
14	// Amounts are MONEY, so they are asserted in the app's money format — a dollar sign and two decimals,
15	// "$120.00" — per the "show money properly everywhere" change (see money-format.spec.ts). The amounts
16	// are picked so no value is a substring of another or of the total, and all stay below 1000 so no
17	// thousands separator is involved.
18	import { test, expect } from '@playwright/test';
19	import { resetAndSeed } from '../support/seed';
20	
21	test.describe('project invoices', () => {
22	  test('opening a project shows its invoices and what they add up to', async ({ page }) => {
